74	
75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
82	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
83	     */
84	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
85	
86	    /**
87	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
88	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
89	     */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /**
97	     * Source of the monotonically increasing {@code seq} stamped on each {@link OwnerCreatedEvent}.
98	     * Incremented once per successful create so the emitted events form a gap-free, strictly increasing
99	     * sequence across all creates handled by this application instance.
100	     */
101	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
102	
103	    /** Request header carrying the client-supplied idempotency key for owner creation. */
104	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
105	
106	    /**
107	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
108	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
109	     * creating a duplicate, making owner creation idempotent with respect to the key.
110	     */
111	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
112	
113	    private final ClinicService clinicService;
114	
115	    private final OwnerMapper ownerMapper;
116	
117	    private final PetMapper petMapper;
118	
119	    private final VisitMapper visitMapper;
120	
121	    /** Serializes the structured {@link OwnerCreatedEvent} to JSON for the {@code AUDIT} logger. */
122	    private final ObjectMapper objectMapper;
123	
124	    public OwnerRestControllerV1(ClinicService clinicService,
125	                                 OwnerMapper ownerMapper,
126	                                 PetMapper petMapper,
127	                                 VisitMapper visitMapper,
128	                                 ObjectMapper objectMapper) {
129	        this.clinicService = clinicService;
130	        this.ownerMapper = ownerMapper;
131	        this.petMapper = petMapper;
132	        this.visitMapper = visitMapper;
133	        this.objectMapper = objectMapper;
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
139	        Collection<Owner> owners;
140	        if (lastName != null) {
141	            owners = this.clinicService.findOwnerByLastName(lastName);
142	        } else {
143	            owners = this.clinicService.findAllOwners();
144	        }
145	        if (owners.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        List<OwnerDto> ownerDtos = owners.stream()
149	            .map(this::toOwnerDtoWithBulkWarning)
150	            .toList();
151	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        String idempotencyKey = currentIdempotencyKey();
168	        if (idempotencyKey != null) {
169	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
170	            if (existingId != null) {
171	                Owner existing = this.clinicService.findOwnerById(existingId);
172	                if (existing != null) {
173	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
174	                }
175	            }
176	        }
177	        List<String> missingFields = new ArrayList<>();
178	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
179	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
180	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
181	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
182	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
183	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
184	        String normalizedAddress = hasStructuredAddress
185	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
186	            : normalizedFlatAddress;
187	        requireNonBlank(missingFields, "address", normalizedAddress);
188	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
189	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
190	        if (!missingFields.isEmpty()) {
191	            throw new MissingRequiredFieldsException(missingFields);
192	        }
193	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
194	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
195	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
196	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
197	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
198	        requireDailyLimitNotReached(registrationDate);
199	        requireCityBelowCapacity(ownerFieldsDto.getCity());
200	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
201	        ownerFieldsDto.setTelephone(normalizedTelephone);
202	        if (ownerFieldsDto.getEmail() != null) {
203	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
204	        }
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        HttpHeaders headers = new HttpHeaders();
207	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
208	        owner.setAddress(normalizedAddress);
209	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
210	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
211	            ? normalizedAddressLine2 : null);
212	        owner.setRegistrationDate(registrationDate);
