220	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
221	        }
222	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
223	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
224	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
225	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
