420	    /**
421	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
422	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
423	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
424	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
425	     * {@code "+61412345678"}.
426	     *
427	     * @param telephone the raw telephone value from the request
428	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
429	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
430	     */
431	    private static String normalizeTelephone(String telephone) {
432	        String e164 = toE164(telephone);
433	        if (e164 == null) {
434	            throw new InvalidFieldValueException("telephone",
435	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
436	        }
437	        return e164;
438	    }
439	
440	    /**
441	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
442	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
443	     * owners' stored numbers when detecting duplicates.
444	     */
445	    private static String toE164(String telephone) {
446	        if (telephone == null) {
447	            return null;
448	        }
449	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
450	        String digits;
451	        if (cleaned.startsWith("+")) {
452	            digits = cleaned.substring(1);
453	        } else {
454	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
455	            digits = "61" + national;
456	        }
457	        if (!digits.matches("[0-9]{8,15}")) {
458	            return null;
459	        }
460	        if (!hasValidNationalLength(digits)) {
461	            return null;
462	        }
463	        return "+" + digits;
464	    }
465	
466	    /**
467	     * Checks the national-number length against the country code for the country codes that pin one.
468	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
469	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
470	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
471	     */
472	    private static boolean hasValidNationalLength(String digits) {
473	        if (digits.startsWith("61")) {
474	            return digits.length() - 2 == 9;
475	        }
476	        if (digits.startsWith("1")) {
477	            return digits.length() - 1 == 10;
478	        }
479	        return true;
480	    }
