506	    /**
507	     * The number of owners in a single city at or beyond which the {@code capacityWarning} flag is
508	     * raised; the warning is true once a city holds at least this many owners while still remaining
509	     * below {@link #MAX_OWNERS_PER_CITY} (i.e. between 40 and 49 inclusive), signalling that the city
510	     * is approaching its hard capacity limit.
511	     */
512	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
513	
514	    /**
515	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
516	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
517	     * been validated non-blank.
518	     *
519	     * @param city the incoming owner's city (already validated non-blank)
520	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
521	     */
522	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
523	    private static final int MAX_OWNERS_PER_DAY = 100;
