525	    /**
526	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
527	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
528	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
529	     * date rolled forward to a business day), so this caps the number that may be created per day.
530	     *
531	     * @param businessDay the adjusted business-day registration date of the owner being created
532	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
533	     */
534	    /**
535	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
536	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
537	     */
538	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
539	
540	    /**
541	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
542	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
543	     * owner's registration date, otherwise {@code false}.
544	     *
545	     * @param owner the owner to map
546	     * @return the owner DTO with its bulk-signup warning flag populated
547	     */
548	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
549	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
550	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
551	        ownerDto.setCapacityWarning(approachingCityCapacity(owner.getCity()));
552	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
553	        ownerDto.setMembershipPoints(points);
554	        ownerDto.setMembershipLevel(capMembershipLevel(owner, OwnerMapper.membershipLevelFor(points)));
555	        return ownerDto;
556	    }
557	
558	    /**
559	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
560	     * membership level among the other members of its household (existing owners carrying the same
561	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
562	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
563	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
564	     * mapped to a level for its real household size), so the cap does not depend on other capped
565	     * values.
566	     *
567	     * @param owner the owner whose membership level is being computed
568	     * @param level the owner's uncapped membership level derived from its membership points
569	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
570	     *         when the owner has no other household member
571	     */
572	    private int capMembershipLevel(Owner owner, int level) {
573	        String householdId = owner.getHouseholdId();
574	        if (householdId == null) {
575	            return level;
576	        }
577	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
578	            .filter(existing -> !isDeleted(existing))
579	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
580	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
581	            .map(this::membershipLevelForOwner)
582	            .max(Integer::compareTo)
583	            .orElse(null);
584	        if (maxMemberLevel == null) {
585	            return level;
586	        }
587	        return Math.min(level, maxMemberLevel + 1);
588	    }
589	
590	    /**
591	     * Computes an existing household member's membership level: its membership points for its real
592	     * household size mapped to the numeric level. Used to establish the household's current maximum
593	     * level when capping a new owner's level.
594	     */
595	    private int membershipLevelForOwner(Owner owner) {
596	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
597	        return OwnerMapper.membershipLevelFor(points);
598	    }
