600	    /**
601	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
602	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
603	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
604	     * no household.
605	     *
606	     * @param householdId the owner's computed household identifier, or {@code null} when absent
607	     * @return the number of owners in the household
608	     */
609	    private int householdSize(String householdId) {
610	        if (householdId == null) {
611	            return 0;
612	        }
613	        return (int) this.clinicService.findAllOwners().stream()
614	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
615	            .count();
616	    }
