618	    /**
619	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
620	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
621	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
622	     */
623	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
624	        if (registrationDate == null) {
625	            return false;
626	        }
627	        long registeredThatDay = this.clinicService.findAllOwners().stream()
628	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
629	            .count();
630	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
631	    }
