633	    private void requireDailyLimitNotReached(LocalDate businessDay) {
634	        long registeredThatDay = this.clinicService.findAllOwners().stream()
635	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
636	            .count();
637	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
638	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
639	        }
