642	    /**
643	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
644	     * forward, just like a weekend, until it reaches a non-holiday business day.
645	     */
646	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
647	        LocalDate.of(2026, 1, 1),
648	        LocalDate.of(2026, 1, 26),
649	        LocalDate.of(2026, 4, 25),
650	        LocalDate.of(2026, 12, 25),
651	        LocalDate.of(2026, 12, 28));
652	
653	    /**
654	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
655	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
656	     * the effective registration date (whether supplied in the request or defaulted to the server date)
657	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
658	     * from the registration date uses the adjusted date.
659	     *
660	     * @param date the effective registration date (supplied or defaulted), never {@code null}
661	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
662	     */
663	    private static LocalDate toBusinessDay(LocalDate date) {
664	        LocalDate adjusted = date;
665	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
666	            adjusted = adjusted.plusDays(1);
667	        }
668	        return adjusted;
669	    }
670	
671	    /** Whether {@code date} falls on a Saturday or Sunday. */
672	    private static boolean isWeekend(LocalDate date) {
673	        DayOfWeek day = date.getDayOfWeek();
674	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
675	    }
