680	    /**
681	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
682	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
683	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
684	     * present here and accepts any well-formed postcode.
685	     */
686	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
687	        "NSW", new int[] {2000, 2099},
688	        "VIC", new int[] {3000, 3099},
689	        "QLD", new int[] {4000, 4099});
690	
691	    /**
692	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
693	     * optional, so the request contract stays backward-compatible). When present it must be exactly
694	     * four digits and, for a city whose region is known, fall within that region's inclusive range
695	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
696	     * postcode. A malformed or out-of-range value is rejected with a 400.
697	     *
698	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
699	     * @param city the owner's city, used to look up the region whose range constrains the postcode
700	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
701	     */
702	    private void validatePostcode(String postcode, String city) {
703	        if (postcode == null) {
704	            return;
705	        }
706	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
707	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
708	        }
709	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
710	        int[] range = REGION_POSTCODES.get(region);
711	        if (range == null) {
712	            return;
713	        }
714	        int value = Integer.parseInt(postcode);
715	        if (value < range[0] || value > range[1]) {
716	            throw new InvalidFieldValueException("postcode",
717	                "Postcode must be valid for the city's region " + region);
718	        }
719	    }
720	
721	    /**
722	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
723	     * date defaults to the server date). When present it must not be later than the current server
724	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
725	     *
726	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
727	     * @throws InvalidFieldValueException if the supplied date is later than the server date
728	     */
729	    private void validateRegistrationDate(LocalDate registrationDate) {
730	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
731	            throw new InvalidFieldValueException("registrationDate",
732	                "Registration date must not be later than the current date");
733	        }
734	    }
735	
736	    private void requireCityBelowCapacity(String city) {
737	        long cityOwners = this.clinicService.findAllOwners().stream()
738	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
739	            .count();
740	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
741	            throw new CityAtCapacityException(city);
742	        }
743	    }
744	
745	    /**
746	     * Returns whether the owner's city is approaching its capacity: {@code true} when the city already
747	     * holds at least {@link #CITY_CAPACITY_WARNING_THRESHOLD} but fewer than {@link #MAX_OWNERS_PER_CITY}
748	     * owners (i.e. between 40 and 49 inclusive), comparing city names case-insensitively as the hard
749	     * capacity check does. Returns {@code false} when {@code city} is {@code null}.
750	     *
751	     * @param city the owner's city, or {@code null}
752	     * @return {@code true} when the city holds 40 to 49 owners, otherwise {@code false}
753	     */
754	    private boolean approachingCityCapacity(String city) {
755	        if (city == null) {
756	            return false;
757	        }
758	        long cityOwners = this.clinicService.findAllOwners().stream()
759	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
760	            .count();
761	        return cityOwners >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY;
762	    }
763	
764	    /**
765	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
766	     * of any existing owner. The key (the SHA-256 hex digest of {@code normalizedTelephone + '|' +
767	     * lowerEmail + '|' + soundex(lastName)}) is the single consolidated duplicate-detection key that
768	     * replaces the former separate telephone, email and household checks. Because the telephone is
769	     * part of the key, two owners with the same last name and postcode but different telephones have
770	     * different keys and are both allowed (they surface as a soft match instead); only an exact
771	     * full-key match is a duplicate. Soft-deleted owners are ignored, and the email-domain blocklist
772	     * has already been applied when the email was normalized. The key is derived identically for the
773	     * incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
774	     *
775	     * @param owner the incoming owner, with its normalized telephone, email and last name
776	     *              already populated
777	     * @throws DuplicateIdentityException if another owner already has this exact identity key
778	     */
779	    private void requireUniqueIdentity(Owner owner) {
780	        String identityKey = ownerMapper.toIdentityKey(owner);
781	        boolean taken = this.clinicService.findAllOwners().stream()
782	            .filter(existing -> !isDeleted(existing))
783	            .map(ownerMapper::toIdentityKey)
784	            .anyMatch(identityKey::equals);
785	        if (taken) {
786	            throw new DuplicateIdentityException(identityKey);
787	        }
788	    }
789	
790	    /**
791	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
792	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
793	     * duplicate is allowed when the only matching owner has been deleted.
794	     */
795	    private static boolean isDeleted(Owner owner) {
796	        return Boolean.TRUE.equals(owner.getDeleted());
797	    }
798	
799	    /**
800	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate identity
801	     * check has passed, so the owner is known not to be a rejected duplicate. When an existing owner
802	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
803	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
804	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
805	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
806	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
807	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
808	     *
809	     * @param owner the incoming owner, with its telephone, email and postcode populated
810	     * @param sharesHousehold whether the request opted in as a declared household member
811	     */
812	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
813	        owner.setPossibleDuplicate(false);
814	        owner.setPossibleDuplicateOf(null);
815	        if (sharesHousehold) {
816	            return;
817	        }
818	        String postcode = owner.getPostcode();
819	        if (postcode == null || postcode.isBlank()) {
820	            return;
821	        }
822	        String soundex = OwnerIdentity.soundex(owner.getLastName());
823	        String identityKey = ownerMapper.toIdentityKey(owner);
824	        this.clinicService.findAllOwners().stream()
825	            .filter(existing -> !isDeleted(existing))
826	            .filter(existing -> postcode.equals(existing.getPostcode()))
827	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
828	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
829	            .min(java.util.Comparator.comparing(Owner::getId))
830	            .ifPresent(match -> {
831	                owner.setPossibleDuplicate(true);
832	                owner.setPossibleDuplicateOf(match.getId());
833	            });
834	    }
835	
836	    /**
837	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
838	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
839	     * comparisons are case-insensitive.
840	     */
841	    private static String normalizeForHousehold(String value) {
842	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
843	    }
844	
845	    /**
846	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
847	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
848	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
849	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
850	     * value normalizes to the empty string, so the required-field check rejects an address that is
851	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
852	     *
853	     * @param address the raw address value from the request (may be {@code null})
854	     * @return the normalized address, or the empty string when blank after normalization
855	     */
856	    private static String normalizeAddress(String address) {
857	        if (address == null) {
858	            return "";
859	        }
860	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
861	        if (collapsed.isEmpty()) {
862	            return "";
863	        }
864	        String[] tokens = collapsed.split(" ");
865	        StringBuilder sb = new StringBuilder();
866	        for (String token : tokens) {
867	            String expanded = switch (token) {
868	                case "ST" -> "STREET";
869	                case "RD" -> "ROAD";
870	                case "AVE" -> "AVENUE";
871	                default -> token;
872	            };
873	            if (sb.length() > 0) {
874	                sb.append(' ');
875	            }
876	            sb.append(expanded);
877	        }
878	        return sb.toString();
879	    }
880	
881	    /**
882	     * Composes the stored/returned {@code address} from the normalized structured lines: the
883	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
884	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
885	     * normalized via {@link #normalizeAddress(String)}.
886	     *
887	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
888	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
889	     * @return the composed address string
890	     */
891	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
892	        if (normalizedAddressLine2.isEmpty()) {
893	            return normalizedAddressLine1;
894	        }
895	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
896	    }
897	
898	    /**
899	     * Derives the stable household identifier for an owner from its last name and postcode as the
900	     * upper-cased first 12 hex characters of the SHA-256 digest of
901	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
902	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
903	     * identifier is a deterministic function of the normalized last name and postcode, owners that
904	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
905	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
906	     * postcode and there is then nothing to key on.
907	     *
908	     * @param lastName the owner's last name (already validated non-blank)
909	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
910	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
911	     */
912	    private static String householdIdFor(String lastName, String postcode) {
913	        if (postcode == null || postcode.isBlank()) {
914	            return null;
915	        }
916	        String normalizedLastName = normalizeForHousehold(lastName);
917	        try {
918	            byte[] digest = MessageDigest.getInstance("SHA-256")
919	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
920	            StringBuilder sb = new StringBuilder();
921	            for (byte b : digest) {
922	                sb.append(String.format("%02X", b));
923	            }
924	            return sb.substring(0, 12);
925	        }
926	        catch (NoSuchAlgorithmException e) {
927	            throw new IllegalStateException("SHA-256 not available", e);
928	        }
929	    }
930	}
