53	    /**
54	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
55	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
56	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
57	     * {@code null} when either the birth date or the registration date is absent.
58	     */
59	    @Named("toAgeBand")
60	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
61	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
62	            return null;
63	        }
64	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
65	        if (age < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (age < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
76	     * the former separate telephone, email and household checks. It is the lower-case, 64-character
77	     * SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
78	     * where {@code lowerEmail} is the email trimmed and lower-cased (or the empty string when absent)
79	     * and {@code soundex(lastName)} is the American Soundex code of the owner's last name. Because the
80	     * telephone is part of the key, two owners with the same last name (same soundex) and postcode but
81	     * different telephones have different identity keys; only an exact full-key match is a duplicate.
82	     */
83	    @Named("toIdentityKey")
84	    default String toIdentityKey(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
89	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
90	        String soundex = OwnerIdentity.soundex(owner.getLastName());
91	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + soundex);
92	    }
93	
94	    /**
95	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}: one of
96	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
97	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's {@code membershipLevel}
98	     * is {@code 3} or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
99	     * locality is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
100	     * {@code 'REGIONAL'}.
101	     */
102	    @Named("toOwnerSegment")
103	    default OwnerDto.OwnerSegmentEnum toOwnerSegment(Owner owner) {
104	        if (owner == null) {
105	            return null;
106	        }
107	        Integer membershipLevel = toMembershipLevel(owner);
108	        boolean premium = membershipLevel != null && membershipLevel >= 3;
109	        boolean metro = REGION_TIMEZONE.containsKey(toLocality(owner));
110	        if (premium) {
111	            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
112	        }
113	        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
114	    }
115	
116	    /**
117	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
118	     * email, otherwise {@code 'PHONE'}.
119	     */
120	    @Named("toContactPreference")
121	    default String toContactPreference(Owner owner) {
122	        if (owner == null) {
123	            return null;
124	        }
125	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
126	        return hasEmail ? "EMAIL" : "PHONE";
127	    }
128	
129	    /**
130	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
131	     */
132	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
133	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
134	
135	    /**
136	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
137	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
138	     */
139	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
140	        "NSW", "Australia/Sydney",
141	        "VIC", "Australia/Melbourne",
142	        "QLD", "Australia/Brisbane");
143	
144	    /**
145	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
146	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
147	     * owner's locality from its postcode in preference to its city.
148	     */
149	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
150	        "NSW", new int[] {2000, 2099},
151	        "VIC", new int[] {3000, 3099},
152	        "QLD", new int[] {4000, 4099});
153	
154	    /**
155	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
156	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
157	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
158	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
159	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
160	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
161	     * the same region for known cities but disambiguates cities that share a name.
162	     */
163	    default String toRegion(Owner owner) {
164	        if (owner == null) {
165	            return null;
166	        }
167	        String regionByPostcode = regionForPostcode(owner.getPostcode());
168	        if (regionByPostcode != null) {
169	            return regionByPostcode;
170	        }
171	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
172	    }
173	
174	    /**
175	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
176	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
177	     * the customer code's identity rather than being computed independently. When the customer code
178	     * is absent the region is derived directly from the owner's postcode and city via
179	     * {@link #toRegion(Owner)}.
180	     */
181	    @Named("toLocality")
182	    default String toLocality(Owner owner) {
183	        if (owner == null) {
184	            return null;
185	        }
186	        String customerCode = owner.getCustomerCode();
187	        if (customerCode != null) {
188	            int dash = customerCode.indexOf('-');
189	            if (dash >= 0) {
190	                return customerCode.substring(0, dash);
191	            }
192	        }
193	        return toRegion(owner);
194	    }
195	
196	    /**
197	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
198	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
199	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
200	     * owner's region is not one of the tabled regions.
201	     */
202	    @Named("toTimezone")
203	    default String toTimezone(Owner owner) {
204	        if (owner == null) {
205	            return null;
206	        }
207	        return REGION_TIMEZONE.get(toLocality(owner));
208	    }
209	
210	    /**
211	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
212	     * {@code null} when the postcode is absent, malformed, or in no known range.
213	     */
214	    private static String regionForPostcode(String postcode) {
215	        if (postcode == null || !postcode.matches("\\d{4}")) {
216	            return null;
217	        }
218	        int value = Integer.parseInt(postcode);
219	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
220	            int[] range = entry.getValue();
221	            if (value >= range[0] && value <= range[1]) {
222	                return entry.getKey();
223	            }
224	        }
225	        return null;
226	    }
227	
228	    /**
229	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
230	     */
231	    @Named("toDisplayName")
232	    default String toDisplayName(Owner owner) {
233	        if (owner == null) {
234	            return null;
235	        }
236	        return owner.getLastName() + ", " + owner.getFirstName();
237	    }
238	
239	    /**
240	     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
241	     * by a single space when a title is present, or just the {@code lastName} when no title is
242	     * supplied (absent or blank).
243	     */
244	    @Named("toSalutation")
245	    default String toSalutation(Owner owner) {
246	        if (owner == null) {
247	            return null;
248	        }
249	        String title = owner.getTitle();
250	        if (title == null || title.isBlank()) {
251	            return owner.getLastName();
252	        }
253	        return title + " " + owner.getLastName();
254	    }
255	
256	    /**
257	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
258	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
259	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
260	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
261	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
262	     * untouched.
263	     */
264	    @Named("toTelephoneDisplay")
265	    default String toTelephoneDisplay(Owner owner) {
266	        if (owner == null) {
267	            return null;
268	        }
269	        String telephone = owner.getTelephone();
270	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
271	            return telephone;
272	        }
273	        String digits = telephone.substring(1);
274	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
275	        String countryCode = digits.substring(0, countryCodeLength);
276	        String national = digits.substring(countryCodeLength);
277	        StringBuilder sb = new StringBuilder("+").append(countryCode);
278	        for (int i = 0; i < national.length(); i++) {
279	            if (i % 3 == 0) {
280	                sb.append(' ');
281	            }
282	            sb.append(national.charAt(i));
283	        }
284	        return sb.toString();
285	    }
286	
287	    /**
288	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
289	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
290	     */
291	    @Named("toInitials")
292	    default String toInitials(Owner owner) {
293	        if (owner == null) {
294	            return null;
295	        }
296	        return initial(owner.getFirstName()) + initial(owner.getLastName());
297	    }
298	
299	    /**
300	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
301	     * the last two digits of the fiscal year of the {@code registrationDate}, e.g.
302	     * {@code 'NSW-1A2B3C4D-M26'}. The fiscal year starts on 1 July and is identified by the calendar
303	     * year in which it ends. Returns {@code null} when either the customer code or the registration
304	     * date is absent.
305	     */
306	    @Named("toMembershipNumber")
307	    default String toMembershipNumber(Owner owner) {
308	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
309	            return null;
310	        }
311	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear(owner.getRegistrationDate()) % 100);
312	    }
313	
314	    /**
315	     * Derives the owner's {@code fiscalYear} from its {@code registrationDate}, formatted
316	     * {@code 'FY<YY>'} where {@code YY} is the last two digits of the fiscal year, e.g. {@code 'FY26'}.
317	     * The fiscal year starts on 1 July and is identified by the calendar year in which it ends: a date
318	     * from 1 July onwards belongs to the fiscal year ending in the following calendar year, and a date
319	     * before 1 July to the fiscal year ending in the same calendar year. Returns {@code null} when the
320	     * registration date is absent.
321	     */
322	    @Named("toFiscalYear")
323	    default String toFiscalYear(Owner owner) {
324	        if (owner == null || owner.getRegistrationDate() == null) {
325	            return null;
326	        }
327	        return String.format("FY%02d", fiscalYear(owner.getRegistrationDate()) % 100);
328	    }
329	
330	    /**
331	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
332	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
333	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
334	     * in its own calendar year.
335	     *
336	     * @param date the date whose fiscal year is computed, never {@code null}
337	     * @return the calendar year in which the date's fiscal year ends
338	     */
339	    static int fiscalYear(LocalDate date) {
340	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
341	    }
342	
343	    /**
344	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
345	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
346	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
347	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
348	     * This qualified mapping cannot observe the owner's household size (which requires counting other
349	     * owners), so it computes the points as if the owner were the only member of its household; the
350	     * controller recomputes the points with the real household size via
351	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
352	     */
353	    @Named("toMembershipPoints")
354	    default Integer toMembershipPoints(Owner owner) {
355	        if (owner == null) {
356	            return null;
357	        }
358	        return membershipPointsFor(owner, 1);
359	    }
360	
361	    /**
362	     * Returns the owner's numeric membership level, derived from its membership points: level
363	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
364	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
365	     * is not observable here and is treated as a single member.
366	     */
367	    @Named("toMembershipLevel")
368	    default Integer toMembershipLevel(Owner owner) {
369	        if (owner == null) {
370	            return null;
371	        }
372	        return membershipLevelFor(membershipPointsFor(owner, 1));
373	    }
374	
375	    /**
376	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
377	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
378	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
379	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
380	     * the {@code registrationDate} and today.
381	     *
382	     * @param owner the owner whose points are computed, never {@code null}
383	     * @param householdSize the number of owners sharing the owner's household
384	     * @return the owner's membership points
385	     */
386	    static int membershipPointsFor(Owner owner, int householdSize) {
387	        int points = 0;
388	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
389	        if (hasEmail) {
390	            points += 2;
391	        }
392	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
393	        if (noNamesakes) {
394	            points += 1;
395	        }
396	        if (householdSize >= 3) {
397	            points += 2;
398	        }
399	        boolean tenured = owner.getRegistrationDate() != null
400	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
401	        if (tenured) {
402	            points += 3;
403	        }
404	        return points;
405	    }
406	
407	    /**
408	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
409	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
410	     *
411	     * @param points the owner's membership points
412	     * @return the corresponding membership level (1-4)
413	     */
414	    static int membershipLevelFor(int points) {
415	        if (points <= 1) {
416	            return 1;
417	        }
418	        if (points <= 3) {
419	            return 2;
420	        }
421	        if (points <= 5) {
422	            return 3;
423	        }
424	        return 4;
425	    }
426	
427	    /**
428	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
429	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
430	     * absent.
431	     */
432	    @Named("toCheckDigit")
433	    default Integer toCheckDigit(Owner owner) {
434	        if (owner == null || owner.getCustomerCode() == null) {
435	            return null;
436	        }
437	        int sum = 0;
438	        boolean dbl = true;
439	        String code = owner.getCustomerCode();
440	        for (int i = code.length() - 1; i >= 0; i--) {
441	            char c = code.charAt(i);
442	            if (c < '0' || c > '9') {
443	                continue;
444	            }
445	            int d = c - '0';
446	            if (dbl) {
447	                d *= 2;
448	                if (d > 9) {
449	                    d -= 9;
450	                }
451	            }
452	            sum += d;
453	            dbl = !dbl;
454	        }
455	        return (10 - (sum % 10)) % 10;
456	    }
457	
458	    private static String initial(String name) {
459	        if (name == null || name.isEmpty()) {
460	            return "";
461	        }
462	        return Character.toUpperCase(name.charAt(0)) + ".";
463	    }
464	
465	    Owner toOwner(OwnerDto ownerDto);
466	
467	    @Mapping(target = "id", ignore = true)
468	    @Mapping(target = "pets", ignore = true)
469	    Owner toOwner(OwnerFieldsDto ownerDto);
470	
471	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
472	
473	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
474	
475	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
476	        OwnerPageDto ownerPageDto = new OwnerPageDto();
477	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
478	        ownerPageDto.setPage(ownerPage.getNumber());
479	        ownerPageDto.setSize(ownerPage.getSize());
480	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
481	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
482	        return ownerPageDto;
483	    }
484	}
